using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public static class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt that asks for a concise summary of the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize.")] string content,
        [Description("Optional desired length: short, medium, or long.")] string? length = "medium")
    {
        var systemInstruction = length switch
        {
            "short" => "Summarize the following text in 1-2 sentences.",
            "long" => "Provide a detailed summary of the following text, preserving key details.",
            _ => "Summarize the following text in a concise paragraph."
        };

        return
        [
            new()
            {
                Role = Role.User,
                Content = new Content { Type = "text", Text = $"{systemInstruction}\n\n{content}" }
            }
        ];
    }
}

